const { Given, When, Then, Before } = require('@cucumber/cucumber');
const assert = require('assert');

// ──────────────────────────────────────────────
// Helpers
// ──────────────────────────────────────────────

function getTodoItems(doc) {
  return Array.from(doc.querySelectorAll('.todo-list li'));
}

function findTodoItem(doc, title) {
  return getTodoItems(doc).find(li => li.querySelector('label').textContent.trim() === title);
}

function getTodoItemByText(doc, text) {
  return getTodoItems(doc).filter(li => li.querySelector('label').textContent.trim() === text);
}

function waitFor(fn, timeout=200) {
  return new Promise((resolve, reject) => {
    const start = Date.now();
    function check() {
      const result = fn();
      if (result !== undefined) return resolve(result);
      if (Date.now() - start >= timeout) return reject(new Error('waitFor timeout'));
      setTimeout(check, 10);
    }
    check();
  });
}

// ──────────────────────────────────────────────
// Given steps
// ──────────────────────────────────────────────

Given('the TodoMVC app is open', function () {
  // The app is loaded by Before hook in world.js
});

Given('the app has no todos', function () {
  const items = getTodoItems(this.document);
  if (items.length > 0) {
    // Remove all existing todos from localStorage and reload
    this.localStorage.clear();
    this.window.location.reload();
  }
});

Given('the input field is focused', function () {
  const input = this.document.querySelector('.new-todo');
  input.focus();
  this.document.activeElement = input;
});

Given('the todo list contains {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', which: 13, keyCode: 13, bubbles: true }));
  // Focus back on input after creating
  input.focus();
  this.document.activeElement = input;
});

Given('the todo list contains {string} and {string}', function (title1, title2) {
  const input = this.document.querySelector('.new-todo');
  [title1, title2].forEach(t => {
    input.value = t;
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', which: 13, keyCode: 13, bubbles: true }));
  });
  input.focus();
  this.document.activeElement = input;
});

Given('the todo list contains {string}, {string}, and {string}', function (title1, title2, title3) {
  const input = this.document.querySelector('.new-todo');
  [title1, title2, title3].forEach(t => {
    input.value = t;
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', which: 13, keyCode: 13, bubbles: true }));
  });
  input.focus();
  this.document.activeElement = input;
});

Given('the todo list contains a completed todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', which: 13, keyCode: 13, bubbles: true }));
  // Mark as completed
  const item = findTodoItem(this.document, title);
  if (item) {
    item.querySelector('.toggle').click();
  }
  input.focus();
  this.document.activeElement = input;
});

Given('the app is at the default route', function () {
  this.navigate('#/');
});

Given('I am on the {string} route', function (hash) {
  this.navigate(hash);
});



Given('localStorage contains an active todo {string}', function (title) {
  const data = JSON.parse(this.localStorage.getItem('todos-todomvc') || '[]');
  data.push({ id: Date.now(), title: title, completed: false });
  this.localStorage.setItem('todos-todomvc', JSON.stringify(data));
});

Given('localStorage contains a completed todo {string}', function (title) {
  const data = JSON.parse(this.localStorage.getItem('todos-todomvc') || '[]');
  data.push({ id: Date.now(), title: title, completed: true });
  this.localStorage.setItem('todos-todomvc', JSON.stringify(data));
});

Given('localStorage contains todos {string} and {string}', function (title1, title2) {
  const data = JSON.parse(this.localStorage.getItem('todos-todomvc') || '[]');
  data.push({ id: Date.now() + 1, title: title1, completed: false });
  data.push({ id: Date.now() + 2, title: title2, completed: false });
  this.localStorage.setItem('todos-todomvc', JSON.stringify(data));
});

Given('all todos are marked as completed', function () {
  const items = getTodoItems(this.document);
  items.forEach(function(li) {
    const toggle = li.querySelector('.toggle');
    if (!toggle.checked) toggle.click();
  });
});

Given('localStorage has no todos', function () {
  this.localStorage.removeItem('todos-todomvc');
});

// ──────────────────────────────────────────────
// When steps
// ──────────────────────────────────────────────

When('I type {string} into the new-todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.focus();
  this.document.activeElement = input;
});

When('I press Enter', function () {
  const active = this.document.activeElement;
  if (active) {
    active.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', which: 13, keyCode: 13, bubbles: true }));
  }
});

When('I press Enter with an empty input', function () {
  const input = this.document.querySelector('.new-todo');
  input.value = '';
  input.focus();
  this.document.activeElement = input;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', which: 13, keyCode: 13, bubbles: true }));
});

When('I click the toggle checkbox on {string}', function (title) {
  const item = findTodoItem(this.document, title);
  if (item) {
    item.querySelector('.toggle').click();
  } else {
    throw new Error(`Todo item "${title}" not found`);
  }
});

When('I mark {string} as completed', function (title) {
  // Find the item and click its toggle
  const item = findTodoItem(this.document, title);
  if (item) {
    item.querySelector('.toggle').click();
  } else {
    throw new Error(`Todo item "${title}" not found`);
  }
});

When('I mark {string} as active', function (title) {
  // Same as toggling - uncheck completed todo
  const item = findTodoItem(this.document, title);
  if (item) {
    item.querySelector('.toggle').click();
  } else {
    throw new Error(`Todo item "${title}" not found`);
  }
});

When('I click the {string} filter link', function (filterName) {
  const links = this.document.querySelectorAll('.filters a');
  const link = Array.from(links).find(a => a.textContent.trim() === filterName);
  if (link) {
    link.click();
  } else {
    throw new Error(`Filter link "${filterName}" not found`);
  }
});

When('I click the "Mark all as complete" toggle', function () {
  const toggle = this.document.querySelector('.toggle-all');
  if (toggle) toggle.click();
});

When('I click "Clear completed"', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (btn) btn.click();
});

When('I double-click the label of {string}', function (title) {
  const item = findTodoItem(this.document, title);
  if (item) {
    const label = item.querySelector('label');
    label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
  } else {
    throw new Error(`Todo item "${title}" not found`);
  }
});

When('I double-click the label of {string} to edit it', function (title) {
  const item = findTodoItem(this.document, title);
  if (item) {
    const label = item.querySelector('label');
    label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
  } else {
    throw new Error(`Todo item "${title}" not found`);
  }
});

When('I change the value to {string}', function (newValue) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (editInput) {
    editInput.value = newValue;
  } else {
    throw new Error('No editing input found');
  }
});

When('I change the title of {string} to {string}', function (oldTitle, newTitle) {
  // First double-click to enter edit mode, then change value
  const item = findTodoItem(this.document, oldTitle);
  if (item) {
    const label = item.querySelector('label');
    label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
    // Wait for edit mode
    const editInput = this.document.querySelector('.todo-list li.editing .edit');
    if (editInput) {
      editInput.value = newTitle;
      editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', which: 13, keyCode: 13, bubbles: true }));
    }
  } else {
    throw new Error(`Todo item "${oldTitle}" not found`);
  }
});

When('I blur the edit input', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (editInput) {
    // Use focusout which bubbles (blur does not), so the app.js listener catches it
    editInput.dispatchEvent(new this.window.FocusEvent('focusout', { bubbles: true }));
  }
});

When('I press Escape', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  if (editInput) {
    editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', code: 'Escape', which: 27, keyCode: 27, bubbles: true }));
  }
});

When('I reload the app', function () {
  this.window.location.reload();
});

When('I navigate to the {string} route', function (hash) {
  this.navigate(hash);
});

Given('I navigate to the "#/active" route', function () {
  this.navigate('#/active');
});

// ──────────────────────────────────────────────
// Then steps
// ──────────────────────────────────────────────

Then('the main section should not be visible', function () {
  const main = this.document.querySelector('.main');
  const style = this.window.getComputedStyle(main);
  assert.strictEqual(style.display, 'none', 'Expected main section to be hidden');
});

Then('the footer should not be visible', function () {
  const footer = this.document.querySelector('.footer');
  const style = this.window.getComputedStyle(footer);
  assert.strictEqual(style.display, 'none', 'Expected footer to be hidden');
});

Then('a new todo {string} appears in the list', function (title) {
  const items = getTodoItems(this.document);
  const found = items.some(li => li.querySelector('label').textContent.trim() === title);
  assert.ok(found, `Expected todo "${title}" to appear in the list`);
});

Then('the new-todo input is cleared', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '', 'Expected new-todo input to be cleared');
});

Then('{string} should be marked as completed', function (title) {
  const item = findTodoItem(this.document, title);
  assert.ok(item, `Todo item "${title}" not found`);
  assert.ok(item.classList.contains('completed'), `Expected "${title}" to be marked as completed`);
});

Then('{string} should be marked as active', function (title) {
  const item = findTodoItem(this.document, title);
  assert.ok(item, `Todo item "${title}" not found`);
  assert.ok(!item.classList.contains('completed'), `Expected "${title}" to be marked as active`);
});

Then('all todos should be marked as completed', function () {
  const items = getTodoItems(this.document);
  assert.ok(items.length > 0, 'Expected at least one todo item');
  items.forEach(li => {
    assert.ok(li.classList.contains('completed'), 'Expected all todos to be marked as completed');
  });
});

Then('the "Mark all as complete" checkbox should be checked', function () {
  const toggle = this.document.querySelector('.toggle-all');
  assert.ok(toggle, 'Expected toggle-all checkbox to exist');
  assert.ok(toggle.checked, 'Expected toggle-all checkbox to be checked');
});

Then('the "Mark all as complete" checkbox should not be checked', function () {
  const toggle = this.document.querySelector('.toggle-all');
  assert.ok(toggle, 'Expected toggle-all checkbox to exist');
  assert.ok(!toggle.checked, 'Expected toggle-all checkbox to not be checked');
});

Then('the todo count should show {string}', function (expectedText) {
  const countEl = this.document.querySelector('.todo-count');
  assert.ok(countEl, 'Expected todo-count element to exist');
  assert.strictEqual(countEl.textContent.trim(), expectedText, `Expected todo count to show "${expectedText}"`);
});

Then('no new todo is added to the list', function () {
  // The list should remain empty or unchanged
  // Since there are no todos created, verify items are empty
  const items = getTodoItems(this.document);
  assert.strictEqual(items.length, 0, 'Expected no todos to be added');
});

Then('the todo list should contain {string}', function (title) {
  const item = findTodoItem(this.document, title);
  assert.ok(item, `Expected todo list to contain "${title}"`);
});

Then('the todo list should not contain {string}', function (title) {
  const item = findTodoItem(this.document, title);
  assert.ok(!item, `Expected todo list to not contain "${title}"`);
});

Then('the {string} button should be visible', function (buttonLabel) {
  let btn;
  if (buttonLabel === 'Clear completed') {
    btn = this.document.querySelector('.clear-completed');
  }
  assert.ok(btn, `Expected "${buttonLabel}" button to exist`);
  const style = this.window.getComputedStyle(btn);
  assert.notStrictEqual(style.display, 'none', `Expected "${buttonLabel}" button to be visible`);
});

Then('the {string} button should not be visible', function (buttonLabel) {
  let btn;
  if (buttonLabel === 'Clear completed') {
    btn = this.document.querySelector('.clear-completed');
  }
  assert.ok(btn, `Expected "${buttonLabel}" button to exist`);
  const style = this.window.getComputedStyle(btn);
  assert.strictEqual(style.display, 'none', `Expected "${buttonLabel}" button to be hidden`);
});

Then('the todo item should have the editing class', function () {
  const editing = this.document.querySelector('.todo-list li.editing');
  assert.ok(editing, 'Expected a todo item to have the editing class');
});

Then('the edit input should contain {string}', function (expectedValue) {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'Expected editing input to exist');
  assert.strictEqual(editInput.value, expectedValue, `Expected edit input to contain "${expectedValue}"`);
});

Then('the edit input should be focused', function () {
  const editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert.ok(editInput, 'Expected editing input to exist');
  assert.strictEqual(this.document.activeElement, editInput, 'Expected edit input to be focused');
});

Then('the editing class should be removed', function () {
  const editing = this.document.querySelector('.todo-list li.editing');
  assert.ok(!editing, 'Expected no todo item to have the editing class');
});

Then('the todo should display {string}', function (expectedTitle) {
  const item = findTodoItem(this.document, expectedTitle);
  assert.ok(item, `Expected todo "${expectedTitle}" to exist in the list`);
});

Then('the todo list should show {int} items', function (count) {
  const items = getTodoItems(this.document);
  assert.strictEqual(items.length, count, `Expected ${count} items in the todo list`);
});

Then('the todo list should show {int} item', function (count) {
  const items = getTodoItems(this.document);
  assert.strictEqual(items.length, count, `Expected ${count} items in the todo list`);
});

Then('the displayed items should be {string} and {string}', function (title1, title2) {
  const items = getTodoItems(this.document);
  const titles = items.map(li => li.querySelector('label').textContent.trim());
  assert.strictEqual(titles.length, 2, `Expected 2 displayed items, got ${titles.length}`);
  assert.ok(titles.includes(title1), `Expected displayed items to include "${title1}"`);
  assert.ok(titles.includes(title2), `Expected displayed items to include "${title2}"`);
});

Then('the displayed item should be {string}', function (title) {
  const items = getTodoItems(this.document);
  const titles = items.map(li => li.querySelector('label').textContent.trim());
  assert.strictEqual(titles.length, 1, `Expected 1 displayed item, got ${titles.length}`);
  assert.strictEqual(titles[0], title, `Expected displayed item to be "${title}"`);
});

Then('the displayed items should be {string}', function (title) {
  const items = getTodoItems(this.document);
  const titles = items.map(li => li.querySelector('label').textContent.trim());
  assert.strictEqual(titles.length, 1, `Expected 1 displayed item, got ${titles.length}`);
  assert.strictEqual(titles[0], title, `Expected displayed item to be "${title}"`);
});

Then('the URL hash should be {string}', function (expectedHash) {
  assert.strictEqual(this.window.location.hash, expectedHash, `Expected URL hash to be "${expectedHash}"`);
});

Then('the {string} filter link should have the selected class', function (filterName) {
  const links = this.document.querySelectorAll('.filters a');
  const link = Array.from(links).find(a => a.textContent.trim() === filterName);
  assert.ok(link, `Expected filter link "${filterName}" to exist`);
  assert.ok(link.classList.contains('selected'), `Expected "${filterName}" filter link to have the selected class`);
});

Then('the todos in localStorage should contain {string}', function (title) {
  const data = JSON.parse(this.localStorage.getItem('todos-todomvc') || '[]');
  const found = data.some(t => t.title === title);
  assert.ok(found, `Expected localStorage to contain todo "${title}"`);
});

Then('the localStorage key should be prefixed with {string}', function (prefix) {
  const keys = Object.keys(this.localStorage);
  const matching = keys.filter(k => k.startsWith(prefix));
  assert.ok(matching.length > 0, `Expected a localStorage key prefixed with "${prefix}"`);
});

Then('localStorage should record {string} as completed', function (title) {
  const data = JSON.parse(this.localStorage.getItem('todos-todomvc') || '[]');
  const todo = data.find(t => t.title === title);
  assert.ok(todo, `Expected "${title}" in localStorage`);
  assert.ok(todo.completed, `Expected "${title}" to be recorded as completed`);
});

Then('localStorage should contain {string}', function (title) {
  const data = JSON.parse(this.localStorage.getItem('todos-todomvc') || '[]');
  const found = data.some(t => t.title === title);
  assert.ok(found, `Expected localStorage to contain "${title}"`);
});

Then('localStorage should not contain {string}', function (title) {
  const data = JSON.parse(this.localStorage.getItem('todos-todomvc') || '[]');
  const found = data.some(t => t.title === title);
  assert.ok(!found, `Expected localStorage to not contain "${title}"`);
});

Then('the todos in localStorage should not contain {string}', function (title) {
  const data = JSON.parse(this.localStorage.getItem('todos-todomvc') || '[]');
  const found = data.some(t => t.title === title);
  assert.ok(!found, `Expected localStorage to not contain "${title}"`);
});

Then('the todo list should show only active items', function () {
  const items = getTodoItems(this.document);
  items.forEach(li => {
    assert.ok(!li.classList.contains('completed'), 'Expected all displayed items to be active');
  });
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;

    // Override location.reload to work in happy-dom
    const self = this;
    w.location.reload = function () { self.reload(); };
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  // happy-dom's location.reload() is a no-op; a step that reloads must re-init the app.
  reload() {
    if (!this.window) throw new Error('verification support: reload() before the app was loaded');
    // Preserve localStorage and hash across reload
    const todoData = this.window.localStorage.getItem('todos-todomvc');
    const hash = this.window.location.hash;

    this.disposeApp();
    this.loadApp();

    // Restore localStorage data in the new window
    if (todoData !== null) {
      this.window.localStorage.setItem('todos-todomvc', todoData);
    }
    // Re-render to pick up restored data
    if (typeof this.window.appRender === 'function') {
      this.window.appRender();
    }
    if (hash) {
      this.navigate(hash);
    }
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

(function () {
  'use strict';

  // ──────────────────────────────────────────────
  // Model
  // ──────────────────────────────────────────────

  const STORAGE_KEY = 'todos-todomvc';

  function loadTodos() {
    try {
      const data = localStorage.getItem(STORAGE_KEY);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      return [];
    }
  }

  function saveTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function nextId() {
    const todos = loadTodos();
    return todos.reduce(function (max, t) { return Math.max(max, t.id); }, 0) + 1;
